create or replace function public.dreem_get_learner_fee_statement(p_student_id uuid)
returns table(row_kind text,row_id uuid,label text,occurred_on timestamptz,due_on date,amount numeric,status text,reference text) language plpgsql security definer set search_path='' as $$
declare v_school uuid; v_actor uuid:=(select auth.uid());
begin if v_actor is null then raise exception 'Authentication is required.'; end if; select school_id into v_school from public.students where id=p_student_id; if v_school is null then raise exception 'Learner was not found.'; end if;
 if not (private.dreem_has_role(v_school,array['leadership','bursar','accountant','auditor']) or exists(select 1 from public.students s where s.id=p_student_id and (s.profile_id=v_actor or v_actor=any(coalesce(s.parent_user_ids,array[]::uuid[]))))) then raise exception 'Fee statement access is not authorized.'; end if;
 return query select 'charge',c.id,coalesce(i.label,'School fee'),c.created_at,c.due_on,c.amount-c.waived_amount,c.status,null::text from public.dreem_student_fee_charges c left join public.dreem_fee_plan_items i on i.id=c.fee_plan_item_id where c.student_id=p_student_id and c.school_id=v_school union all select 'payment',p.id,'Payment received',p.received_at,null::date,-p.amount,case when p.reverses_payment_id is null then 'received' else 'reversal' end,p.receipt_number from public.dreem_financial_payments p where p.student_id=p_student_id and p.school_id=v_school union all select 'adjustment',a.id,replace(a.adjustment_type,'_',' '),a.created_at,null::date,-a.amount,a.status,a.reason from public.dreem_fee_adjustments a where a.student_id=p_student_id and a.school_id=v_school order by occurred_on desc; end;$$;
revoke all on function public.dreem_get_learner_fee_statement(uuid) from public; grant execute on function public.dreem_get_learner_fee_statement(uuid) to authenticated;